import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  BackgroundInteractionJournal,
  _deps,
  loadBackgroundInteractionJournal,
  updateBackgroundInteractionJournal,
} from "../../src/lib/background-interaction-journal.js";

function binding(sessionId, overrides = {}) {
  return {
    backgroundAgentId: "bg-journal-1",
    sessionId,
    turnId: "turn-1",
    toolUseId: "tool-1",
    sequence: 1,
    ...overrides,
  };
}

describe("verify-11: problem ownership isolation and no execution rebuild", () => {
  let originalAppend;
  let originalPresence;
  let originalReadVerified;
  // sessionId -> verified event transcript (used by the mocked store).
  const store = new Map();

  beforeEach(() => {
    originalAppend = _deps.appendEventWithVerifiedProjection;
    originalPresence = _deps.getSessionPresence;
    originalReadVerified = _deps.readVerifiedEvents;
    store.clear();
    _deps.appendEventWithVerifiedProjection = vi.fn(
      (sessionId, type, data, { createProjection, validateProjection }) => {
        const projection = createProjection();
        for (const event of store.get(sessionId) || []) {
          projection.accept(structuredClone(event));
        }
        validateProjection(projection.finish());
        if (!store.has(sessionId)) store.set(sessionId, []);
        store.get(sessionId).push({
          sessionId,
          type,
          data: structuredClone(data),
        });
        return { hash: "mock-hash" };
      },
    );
    _deps.readVerifiedEvents = vi.fn((sessionId) =>
      (store.get(sessionId) || []).map(({ type, data }) => ({
        type,
        data: structuredClone(data),
      })),
    );
    _deps.getSessionPresence = vi.fn(() => "present");
  });

  afterEach(() => {
    _deps.appendEventWithVerifiedProjection = originalAppend;
    _deps.getSessionPresence = originalPresence;
    _deps.readVerifiedEvents = originalReadVerified;
  });

  it("keeps a same-named question independent across two in-memory sessions", () => {
    const sessionA = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    const sessionB = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    for (const journal of [sessionA, sessionB]) {
      journal.recordPending({
        requestId: "question",
        binding: binding(journal === sessionA ? "session-a" : "session-b"),
        payload: { question: "Deploy?" },
      });
    }

    // Settling session A's copy leaves session B's copy pending and intact.
    sessionA.settle("question", binding("session-a"), {
      status: "resolved",
      answer: "yes",
    });
    expect(sessionA.get("question")).toMatchObject({
      status: "resolved",
      settlement: { answer: "yes" },
    });
    expect(sessionB.get("question")).toMatchObject({ status: "pending" });

    // Negative control: an answer bound to session A must not settle session B.
    expect(() =>
      sessionB.settle("question", binding("session-a"), {
        status: "resolved",
        answer: "no",
      }),
    ).toThrow(/binding does not match/);
    expect(sessionB.get("question").status).toBe("pending");

    // Session B is still independently settleable to its own distinct answer.
    expect(
      sessionB.settle("question", binding("session-b"), {
        status: "resolved",
        answer: "no",
      }).applied,
    ).toBe(true);
    expect(sessionB.get("question").settlement.answer).toBe("no");
  });

  it("does not cross-contaminate the same-named question across persisted sessions", () => {
    let journalA = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    let journalB = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    journalA = updateBackgroundInteractionJournal(
      "session-a",
      journalA,
      (draft) =>
        draft.recordPending({
          requestId: "question",
          binding: binding("session-a"),
          payload: { question: "Deploy?" },
        }),
    ).journal;
    journalB = updateBackgroundInteractionJournal(
      "session-b",
      journalB,
      (draft) =>
        draft.recordPending({
          requestId: "question",
          binding: binding("session-b"),
          payload: { question: "Deploy?" },
        }),
    ).journal;
    journalA = updateBackgroundInteractionJournal(
      "session-a",
      journalA,
      (draft) =>
        draft.settle("question", binding("session-a"), {
          status: "resolved",
          answer: "yes",
        }),
      { now: () => 200 },
    ).journal;

    const loadedA = loadBackgroundInteractionJournal(
      "session-a",
      "bg-journal-1",
    );
    const loadedB = loadBackgroundInteractionJournal(
      "session-b",
      "bg-journal-1",
    );
    expect(loadedA.get("question")).toMatchObject({
      status: "resolved",
      settlement: { answer: "yes" },
    });
    expect(loadedB.get("question")).toMatchObject({ status: "pending" });
  });

  it("does not rebuild execution when a completed record is replayed identically", () => {
    const journal = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    journal.recordPending({
      requestId: "question",
      binding: binding("session-1"),
      payload: { question: "Deploy?" },
    });
    journal.settle("question", binding("session-1"), {
      status: "resolved",
      answer: "yes",
    });
    expect(journal.pending()).toHaveLength(0);

    // Replaying the same completed request returns applied:false and leaves it terminal.
    const replay = journal.recordPending({
      requestId: "question",
      binding: binding("session-1"),
      payload: { question: "Deploy?" },
    });
    expect(replay.applied).toBe(false);
    expect(journal.get("question")).toMatchObject({
      status: "resolved",
      settlement: { answer: "yes" },
    });
    expect(journal.pending()).toHaveLength(0);
  });

  it("rejects a changed replay of a completed record without rebuilding execution", () => {
    const journal = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    journal.recordPending({
      requestId: "question",
      binding: binding("session-1"),
      payload: { question: "Deploy?" },
    });
    journal.settle("question", binding("session-1"), {
      status: "resolved",
      answer: "yes",
    });

    // Negative control: only the payload changes; the replay must be rejected.
    expect(() =>
      journal.recordPending({
        requestId: "question",
        binding: binding("session-1"),
        payload: { question: "Deploy NOW?" },
      }),
    ).toThrow(/replayed with different binding or payload/);
    expect(journal.get("question")).toMatchObject({
      status: "resolved",
      settlement: { answer: "yes" },
    });
    expect(journal.pending()).toHaveLength(0);
  });

  it("keeps a completed record terminal after a load, refusing to rebuild execution", () => {
    let journal = new BackgroundInteractionJournal({
      backgroundAgentId: "bg-journal-1",
      now: () => 100,
    });
    journal = updateBackgroundInteractionJournal(
      "session-1",
      journal,
      (draft) =>
        draft.recordPending({
          requestId: "question",
          binding: binding("session-1"),
          payload: { question: "Deploy?" },
        }),
    ).journal;
    journal = updateBackgroundInteractionJournal(
      "session-1",
      journal,
      (draft) =>
        draft.settle("question", binding("session-1"), {
          status: "resolved",
          answer: "yes",
        }),
      { now: () => 200 },
    ).journal;

    const loaded = loadBackgroundInteractionJournal("session-1", "bg-journal-1");
    expect(loaded.get("question")).toMatchObject({
      status: "resolved",
      settlement: { answer: "yes" },
    });

    // Replaying the loaded completed request does not resurrect it as pending.
    const replay = loaded.recordPending({
      requestId: "question",
      binding: binding("session-1"),
      payload: { question: "Deploy?" },
    });
    expect(replay.applied).toBe(false);
    expect(loaded.pending()).toHaveLength(0);
    expect(loaded.get("question").status).toBe("resolved");
  });
});

